from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
out='/root/output/result.xlsx'
wb=load_workbook(out, data_only=False)
ws=wb['Task']
print('Validation: formulas (data_only=False)')
for cell in ['H12','H19','H26','H35','H42','H46','H47','H50']:
    print(f'{cell}: {ws[cell].value!r}')

ranges = ['H12:L17','H19:L24','H26:L31','H35:L40','H42:L47','H50:L50']
empty=[]
for rng in ranges:
    for row in ws[rng]:
        for cell in row:
            if cell.value is None or cell.value == '':
                empty.append(cell.coordinate)
print('Empty target cells:', empty if empty else 'None')

bad=[]
for row in ws['H46:L47']:
    for cell in row:
        val = str(cell.value)
        if 'PERCENTILE' not in val or 'PERCENTILE.INC' in val or 'PERCENTILE.EXC' in val:
            bad.append((cell.coordinate, val))
print('Percentile formula issues:', bad if bad else 'None')

# Additional formula sanity checks for all target ranges
nonformula=[]
for rng in ranges:
    for row in ws[rng]:
        for cell in row:
            if not (isinstance(cell.value, str) and cell.value.startswith('=')):
                nonformula.append((cell.coordinate, cell.value))
print('Non-formula target cells:', nonformula if nonformula else 'None')

wbv=load_workbook(out, data_only=True)
wsv=wbv['Task']
print('Validation: sample cached values (data_only=True; may be None without calc engine)')
for cell in ['H12','I12','H35','H42','H46','H47','H50']:
    print(f'{cell}: {wsv[cell].value!r}')
